    let (code, s) = match (*st).resolve_wait(at, tries) {
        Resolved::Found(_, Slot::Valid(a)) => (0, Arc::into_raw(a)),
        Resolved::Found(_, Slot::Invalid) => (1, ptr::null()),
        Resolved::Pending => (2, ptr::null()),
        Resolved::NotVisible => (3, ptr::null()),
    };
    if !status.is_null() {
        *status = code;
    }
